-- Prevent direct creation, decision or deletion of deal approval rows.
create or replace function public.deal_approval_hard_lock_v1() returns trigger language plpgsql set search_path=public as $$begin if current_user not in ('postgres','service_role') then if tg_op='INSERT' and new.entity_type='deal' then raise exception 'Deal approvals must be created through the controlled deal approval workflow.';end if;if tg_op='UPDATE' and (old.entity_type='deal' or new.entity_type='deal') then raise exception 'Deal approval decisions must use the controlled deal approval workflow.';end if;if tg_op='DELETE' and old.entity_type='deal' then raise exception 'Deal approval history cannot be deleted directly.';end if;end if;if tg_op='DELETE' then return old;else return new;end if;end$$;
drop trigger if exists trg_deal_approval_hard_lock on public.approvals;create trigger trg_deal_approval_hard_lock before insert or update or delete on public.approvals for each row execute function public.deal_approval_hard_lock_v1();
revoke all on function public.deal_approval_hard_lock_v1() from public,anon;revoke all on function public.deal_creation_integrity_guard() from public,anon;revoke all on function public.deal_sensitive_update_guard() from public,anon;revoke all on function public.deal_commercial_lock_guard() from public,anon;
